/* Dedicated full-resolution staff; guild contacts keep their existing catalogue. */
export async function createShopCharacters(guild,baseURL){
 const response=await fetch(new URL('assets/shopkeepers-v2/manifest.json?v=1',baseURL));if(!response.ok)throw Error('Shopkeeper catalogue unavailable');const entries=(await response.json()).characters,images=new Map(),pending=new Map();
 function ensure(id){const m=entries[id];if(!m)return guild.ensure(id);if(images.has(id))return Promise.resolve(m);if(pending.has(id))return pending.get(id);const request=new Promise((resolve,reject)=>{const image=new Image(),timer=setTimeout(()=>reject(Error('Shopkeeper art timed out')),15000);image.onload=()=>{clearTimeout(timer);images.set(id,image);while(images.size>3)images.delete(images.keys().next().value);resolve(m);};image.onerror=()=>{clearTimeout(timer);reject(Error('Shopkeeper art could not load'));};image.src=new URL(m.image,baseURL).href;}).finally(()=>pending.delete(id));pending.set(id,request);return request;}
 function draw(g,meta,pose,x,y,height){const m=entries[meta.id];if(!m)return guild.draw(g,meta,pose,x,y,height);const image=images.get(meta.id);if(!image)return false;const h=height*(m.relativeHeight||1),scale=h/m.visibleHeight;g.save();g.translate(x,y);if(pose.facing>0)g.scale(-1,1);g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';g.drawImage(image,-m.footX*scale,-m.footY*scale,m.width*scale,m.height*scale);g.restore();return {drawn:true,source:'shopkeepers-v2',nativeHeight:m.visibleHeight};}
 return {ensure,draw,get:id=>entries[id]?(images.has(id)?entries[id]:null):guild.get(id),request(id){if(entries[id])ensure(id).catch(()=>{});else guild.request(id);},report:()=>({dedicated:Object.keys(entries).length,loaded:images.size}),entries};
}
